<script setup lang="ts">
import { computed, ref } from 'vue'
import { useLearning } from '../store'
const store=useLearning(),filter=ref('bookmarks'),error=ref('')
const lessons=computed(()=>store.course?.lessons.filter(l=>(filter.value==='bookmarks'?store.bookmarks:store.progress.completed).includes(l.id)) ?? [])
async function unmark(id:string){error.value='';try{await store.toggleBookmark(id)}catch(e){error.value=(e as Error).message}}
</script>
<template><div class="page narrow-page"><span class="eyebrow">ВАША ЛИЧНАЯ ПРАКТИКА</span><h1>Вернуться.<br>Понять глубже.</h1><p class="lead">Сохраняйте сложные темы в закладки и повторяйте пройденное. Повтор не начисляет XP заново.</p><div class="segmented" aria-label="Тип повторения"><button :aria-pressed="filter==='bookmarks'" :class="{selected:filter==='bookmarks'}" @click="filter='bookmarks'">Закладки · {{ store.bookmarks.length }}</button><button :aria-pressed="filter==='completed'" :class="{selected:filter==='completed'}" @click="filter='completed'">Пройдено · {{ store.progress.completed.length }}</button></div><p v-if="error" role="alert" class="feedback error-feedback">{{ error }}</p><div v-if="!lessons.length" class="empty-state"><h2>{{ filter==='bookmarks'?'Пока без закладок':'Первые победы ещё впереди' }}</h2><p>{{ filter==='bookmarks'?'В уроке нажмите «Сохранить тему». Закладки сохраняются в базе и остаются после перезагрузки.':'Начните с короткого урока на вашем уровне.' }}</p><RouterLink to="/" class="primary">Открыть курс →</RouterLink></div><div v-for="lesson in lessons" :key="lesson.id" class="review-row"><div><span class="eyebrow">{{ store.course?.tracks.find(t=>t.id===lesson.track)?.title }}</span><h3>{{ lesson.title }}</h3><p>{{ lesson.summary }}</p></div><div class="review-actions"><RouterLink v-if="store.isUnlocked(lesson.id)" :to="`/learn/${lesson.id}`" class="text-link">Открыть →</RouterLink><span v-else class="subtle">Нужен предыдущий урок</span><button v-if="filter==='bookmarks'" class="secondary" :disabled="store.bookmarkBusy" @click="unmark(lesson.id)">Убрать</button></div></div></div></template>
